<div class="page-heading"><div><span class="eyebrow">Community workspace</span><h1><?= e($config['title']) ?></h1><p class="muted"><?= number_format($count) ?> <?= $archived ? 'archived' : 'active' ?> records<?= $user['type']==='official' && in_array($resourceName,['resident-records','resident-surveys','barangay-surveys'],true) ? ' · ' . e($user['brgy_location']) : '' ?></p></div><?php if (can_write($resourceName) && !$archived): ?><?= button($resourceName==='messages' ? 'Write a message' : 'Add record',['href'=>url('edit',['resource'=>$resourceName])]) ?><?php endif; ?></div>
<section class="card">
    <div class="toolbar"><form method="get" class="search-form"><input type="hidden" name="page" value="records"><input type="hidden" name="resource" value="<?= e($resourceName) ?>"><input type="hidden" name="archived" value="<?= $archived ? '1' : '0' ?>"><?= field('q','Search records',$search,['type'=>'search','maxlength'=>200,'placeholder'=>'Search this list']) ?><?= button('Search',['variant'=>'secondary']) ?></form><div class="actions">
        <?php if (can_archive($resourceName)): ?><?= button($archived ? 'Active records' : 'Archive',['href'=>url('records',['resource'=>$resourceName,'archived'=>$archived ? '0' : '1']),'variant'=>'quiet']) ?><?php endif; ?>
        <?php if (in_array($resourceName,['accounts','resident-records','official-records','barangays','resident-surveys','barangay-surveys'],true) && !$archived): ?><?= button('Export CSV',['href'=>url('export',['resource'=>$resourceName,'q'=>$search]),'variant'=>'quiet']) ?><?php endif; ?>
    </div></div>
    <?php if (!$rows): ?><?= empty_state('No records found',$search ? 'Try a different search.' : 'Records will appear here when they are added.') ?>
    <?php else: ?><div class="table-scroll"><table><caption class="sr-only"><?= e($config['title']) ?></caption><thead><tr><?php foreach ($config['list'] as $column): ?><th scope="col"><?= e(label($column)) ?></th><?php endforeach; ?><th scope="col">Actions</th></tr></thead><tbody>
    <?php foreach ($rows as $item): $recordId = (string)$item[$config['key']]; ?><tr><?php foreach ($config['list'] as $column): ?><td><?php if ($column==='app_enabled'): ?><?= badge($item[$column] ? 'Enabled' : 'Disabled') ?><?php elseif ($column==='memo_status'): ?><?= badge($item[$column]) ?><?php else: ?><?= e($item[$column] ?: '—') ?><?php endif; ?></td><?php endforeach; ?><td><div class="actions">
        <?php if ($archived): ?><?= action_form('restore',$resourceName,$recordId,'Restore','secondary',true) ?>
        <?php else: ?><?= button('View',['href'=>url('detail',['resource'=>$resourceName,'id'=>$recordId]),'variant'=>'quiet']) ?><?php if (can_write($resourceName)): ?><?= button('Edit',['href'=>url('edit',['resource'=>$resourceName,'id'=>$recordId]),'variant'=>'quiet']) ?><?php endif; ?><?php if (can_archive($resourceName)): ?><?= action_form('archive',$resourceName,$recordId,'Archive','danger',true) ?><?php endif; ?><?php endif; ?>
    </div></td></tr><?php endforeach; ?></tbody></table></div>
    <nav class="pagination" aria-label="Record pages"><?php if ($pageNumber>1): ?><?= button('Previous',['href'=>url('records',['resource'=>$resourceName,'q'=>$search,'archived'=>$archived?'1':'0','p'=>$pageNumber-1]),'variant'=>'secondary']) ?><?php endif; ?><span>Page <?= $pageNumber ?> of <?= max(1,(int)ceil($count/25)) ?></span><?php if ($pageNumber*25<$count): ?><?= button('Next',['href'=>url('records',['resource'=>$resourceName,'q'=>$search,'archived'=>$archived?'1':'0','p'=>$pageNumber+1]),'variant'=>'secondary']) ?><?php endif; ?></nav>
    <?php endif; ?>
</section>
